{"explanation":"Slice both solids at the same height. A cylinder's slice is always a disk of area πr². A cone's slice, a fraction s of the way down from the apex, has radius s·r, so its area is s²·πr². Adding up the slices means finding the area under s² compared with the area under the constant 1, and that ratio is ∫₀¹ s² ds = 1/3. Drag the slider to move the slice and watch the shaded area fill to 1/3.","manimCode":"const title = new Text({ text: 'Cone = 1/3 Cylinder (same base & height)', color: WHITE, fontSize: 30 });
title.moveTo([0, 3.5, 0]);
scene.add(title);

// Left: side view. Cylinder outline (rectangle) and cone (triangle)
const cx = -3.8, r = 1.5, h = 3, base = -1.7;
const cyl = new Rectangle({ width: 2 * r, height: h, color: GRAY });
cyl.moveTo([cx, base + h / 2, 0]);
const cone = new Polygon({ vertices: [[cx - r, base, 0], [cx + r, base, 0], [cx, base + h, 0]], color: BLUE });
cone.setFill(BLUE, 0.3);
scene.add(cyl, cone);

const sliceCyl = new Polygon({ vertices: [[cx - r, 0, 0], [cx + r, 0, 0]], color: ORANGE });
sliceCyl.setStrokeWidth(4).setFillOpacity(0);
const sliceCone = new Polygon({ vertices: [[cx - 0.5, 0, 0], [cx + 0.5, 0, 0]], color: YELLOW });
sliceCone.setStrokeWidth(6).setFillOpacity(0);
scene.add(sliceCyl, sliceCone);

const lbl1 = new Text({ text: 'slice area: cylinder = 1, cone = s²', color: WHITE, fontSize: 20 });
lbl1.moveTo([cx, -2.5, 0]);
scene.add(lbl1);

// Right: area of slice vs. fraction s from apex
const axes = new Axes({ xRange: [0, 1, 0.25], yRange: [0, 1.2, 0.25], xLength: 5, yLength: 3.5, tips: false });
axes.moveTo([3, -0.2, 0]);
const parab = axes.plot(x => x * x, { color: YELLOW });
const top = axes.plot(x => 1, { color: ORANGE });
scene.add(axes, parab, top);

const lblP = new Text({ text: 's²  (cone)', color: YELLOW, fontSize: 22 });
lblP.moveTo(axes.c2p(0.62, 0.25));
const lblT = new Text({ text: '1  (cylinder)', color: ORANGE, fontSize: 22 });
lblT.moveTo(axes.c2p(0.5, 1.12));
const lblX = new Text({ text: 's = distance from apex / h', color: WHITE, fontSize: 20 });
lblX.moveTo([3, -2.7, 0]);
scene.add(lblP, lblT, lblX);

let area = null, dotP = null, ratio = null;
function update(s) {
  const y = base + h - s * h;
  sliceCyl.setVertices([[cx - r, y, 0], [cx + r, y, 0]]);
  sliceCone.setVertices([[cx - r * s, y, 0], [cx + r * s, y, 0]]);
  if (area) scene.remove(area);
  if (dotP) scene.remove(dotP);
  if (ratio) scene.remove(ratio);
  const t = Math.max(s, 0.02);
  area = axes.getArea(parab, [0, t], { color: BLUE, opacity: 0.5 });
  dotP = new Dot({ point: axes.c2p(s, s * s), color: WHITE });
  const frac = (s * s * s / 3).toFixed(3);
  ratio = new Text({ text: 'shaded = s³/3 = ' + frac + '  (→ 1/3 at s=1)', color: WHITE, fontSize: 22 });
  ratio.moveTo([3, 2.3, 0]);
  scene.add(area, dotP, ratio);
}
update(0.5);

const controls = new Controls(scene, { position: 'bottom-left' });
controls.addSlider({ label: 's', min: 0.02, max: 1, value: 0.5, step: 0.01, onChange: (v) => update(v) });

await scene.wait(999999);"}

